window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"h_HqdtA08Cg","speaker":"Abdoulaye Diop","role":"Foreign Minister","country":"Mali","region":"Africa","url":"https://www.youtube.com/watch?v=h_HqdtA08Cg","date":"20260928","title":"🇲🇱 Mali - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1424,"words":2596,"counts":{"claims":34,"promises":4,"attacks":4},"topics":[{"topic":"Sahel security","share":0.1136,"seconds":162},{"topic":"Mali security","share":0.1123,"seconds":160},{"topic":"Mali economy","share":0.1065,"seconds":152},{"topic":"Mali counter-terrorism","share":0.0563,"seconds":80},{"topic":"UN reform","share":0.053,"seconds":75},{"topic":"Libya","share":0.0515,"seconds":73},{"topic":"Mali AI","share":0.0501,"seconds":71},{"topic":"UN sanctions","share":0.05,"seconds":71},{"topic":"Mali UN","share":0.0482,"seconds":69},{"topic":"Mali independence","share":0.0473,"seconds":67},{"topic":"AI policy","share":0.0472,"seconds":67},{"topic":"Mali constitution","share":0.047,"seconds":67},{"topic":"Ukraine","share":0.0452,"seconds":64},{"topic":"Mali foreign policy","share":0.0445,"seconds":63},{"topic":"UNGA","share":0.0429,"seconds":61},{"topic":"Mali climate","share":0.0423,"seconds":60},{"topic":"Mali sovereignty","share":0.0422,"seconds":60}],"timeline":[[0,65,null],[65,126,"UNGA"],[126,194,"Mali independence"],[195,263,"Mali UN"],[265,336,"UN sanctions"],[336,410,"Libya"],[416,480,"Ukraine"],[482,551,"Mali security"],[553,636,"Sahel security"],[637,716,"Sahel security"],[716,797,"Mali counter-terrorism"],[798,888,"Mali security"],[889,949,"Mali sovereignty"],[951,1028,"Mali economy"],[1029,1104,"Mali economy"],[1105,1172,"Mali constitution"],[1173,1237,"Mali foreign policy"],[1237,1298,"Mali climate"],[1298,1365,"AI policy"],[1366,1437,"Mali AI"],[1438,1514,"UN reform"],[1514,1530,null]],"stances":{"UNGA":"Abdoulaye Diop expresses honor in addressing the assembly on behalf of Mali's President and extends congratulations to the new UNGA President.","Mali independence":"Abdoulaye Diop notes that Mali joined the UN 66 years ago shortly after gaining independence with support from Tunisia and Sri Lanka.","Mali UN":"Abdoulaye Diop states that Mali remains committed to the principles of the UN Charter and warns that deviating from them leads to conflict.","UN sanctions":"Abdoulaye Diop argues that unilateral coercive measures and UN inaction undermine sovereignty and public confidence.","Libya":"Abdoulaye Diop states that NATO's 2011 intervention in Libya worsened regional security and humanitarian conditions, leading to a call for a strategic review of UN offices in West Africa and the Sahel.","Ukraine":"Abdoulaye Diop asserts that Ukraine supports terrorist groups in the Sahel, undermining African territorial integrity despite its own claims to protect it.","Mali security":"Abdoulaye Diop asserts that Mali is facing a destabilization effort supported externally through armed attacks, economic pressure, and media campaigns.","Sahel security":"Abdoulaye Diop states that the 2012 scenario is repeating with terrorist groups forming coalitions against Malian institutions and that previous international responses have failed, leading to the creation of the Confederation of Sahel States.","Mali counter-terrorism":"Abdoulaye Diop asserts that all terrorists are equally unacceptable and outlines Mali's conditions for international cooperation based on sovereignty and non-interference.","Mali sovereignty":"Abdoulaye Diop asserts that Mali's sovereignty is non-negotiable and includes control over economic choices, natural resources, and mining sectors like gold and lithium.","Mali economy":"Abdoulaye Diop states that Mali is implementing ambitious programs and reforms to build a sovereign state and improve economic governance, emphasizing that international assistance alone cannot develop a country.","Mali constitution":"Abdoulaye Diop states that Mali intends to continue its national refoundation and relies primarily on itself for security, well-being, and prosperity.","Mali foreign policy":"Abdoulaye Diop states that Mali will pursue a foreign policy based on sovereign equality, diversified partnerships, and strategic autonomy for itself, the Sahel Confederation, and Africa.","Mali climate":"Abdoulaye Diop states that climate change and desertification are major sources of vulnerability for Mali and the Sahel, affecting agriculture, livelihoods, peace, and security, and calls for adaptation, climate finance, and indigenous solutions.","AI policy":"Abdoulaye Diop argues that nations must master and adapt artificial intelligence rather than merely consume it, emphasizing the need for legal frameworks and investment in skills to ensure digital sovereignty.","Mali AI":"Abdoulaye Diop states that President Assimi Goïta established a Center for Artificial Intelligence Robotics to promote Mali's digital sovereignty.","UN reform":"Abdoulaye Diop calls for a reformed United Nations that is more just, representative, and serves all people, emphasizing the need to strengthen representation for Africa."},"claims":[{"t":150,"quote":"exactly 66 years ago, six days only after becoming independent and sovereign, Mali, under the leadership of President Modibo Keïta, to the UN with the support of the Republic of uh Tunisia and uh of the salon, currently Sri Lanka.","topic":"Mali independence","kind":"fact"},{"t":229,"quote":"Mali reaffirms its unwavering commitment to reformed founded on strict respect respect for the purposes and principles of the United Nations Charter, particularly sovereign equality, territorial integrity, non-use of force, mutual respect, and non-interference in the internal affairs of a state.","topic":"Mali UN","kind":"fact"},{"t":256,"quote":"The further we move away from these principles, the closer we come to cycles of conflict, and we all know that.","topic":"Mali UN","kind":"fact"},{"t":315,"quote":"approximately 30 countries throughout the world which are affected by such sanctions","topic":"UN sanctions","kind":"number"},{"t":348,"quote":"the uh crisis in Libya provoked by the NATO interference in 2011. the uh NATO action in Libya significantly worsened the security, political, humanitarian, and human rights situation in our region through, in particular, the spread of terrorism and violent extremism.","topic":"Libya","kind":"fact"},{"t":416,"quote":"Following uh Ukraine's initial statement in 2024, in which it acknowledged support for terrorist groups operating in the Sahel","topic":"Ukraine","kind":"fact"},{"t":427,"quote":"that country publicly reiterated the highest level of state is interference in Africa","topic":"Ukraine","kind":"fact"},{"t":534,"quote":"The coordinated attacks of 25th April and 4th July 2026 and several locations in Mali caused numerous casualties","topic":"Mali security","kind":"fact"},{"t":554,"quote":"the scenario we witnessed in 12 in 2012 is repeating itself now with terrorist groups and so-called separatist armed groups now forming openly terrorist coalition against Malian institutions and populations","topic":"Sahel security","kind":"fact"},{"t":568,"quote":"Regional and international responses, including the deployment of international forces, have failed to halt these uh complex security crises and massacres affecting the Sahelian populations","topic":"Sahel security","kind":"fact"},{"t":611,"quote":"Our three heads of state took the historic decision on 6th July 2024 in Niamey to create the Confederation of Sahel States","topic":"Sahel security","kind":"fact"},{"t":649,"quote":"The Malian delegation fully endorses that statement that will be delivered by His Excellency Mr. Traoré, Minister of Foreign Affairs of Burkina Faso on behalf of the Confederation of Sahel States which brings together Burkina Faso, the Republic of Mali, and the Republic of Malian forces on their own and also within the AES unified force and with the support of the Russian Federation are today on the front line against imposed terrorism.","topic":"Sahel security","kind":"fact"},{"t":686,"quote":"I would even go so far as to say it's a hybrid war by proxy whose implications extend beyond our region.","topic":"Sahel security","kind":"fact"},{"t":720,"quote":"there is no such a such thing as a good terrorist and a bad terrorist.","topic":"Mali counter-terrorism","kind":"fact"},{"t":725,"quote":"The three AS member countries remain open to cooperation with all partners who respect our main principles governing our countries, namely respect for our sovereignty, territorial integrity, the respect for our strategic choices, including our choices for partnership, and also taking into account the interests of our populations.","topic":"Mali counter-terrorism","kind":"fact"},{"t":798,"quote":"I would like to use this opportunity to pay tribute to all victims of the cowardly barbarism of terrorism who have sacrificed their","topic":"Mali security","kind":"fact"},{"t":891,"quote":"Already, thousands of former combatants who meet the conditions have uh um either joined the defense and security forces or entered civilian employment.","topic":"Mali sovereignty","kind":"number"},{"t":910,"quote":"Sovereignty is not limited to defending our territory. It also means we are controlling our economic choices, that we are managing and developing our natural resources and mining resources, our gold and lithium.","topic":"Mali sovereignty","kind":"fact"},{"t":951,"quote":"These two ambitious programs are designed to meet the legitimate aspirations of the Malian and they constitute a generational pact.","topic":"Mali economy","kind":"fact"},{"t":995,"quote":"the government, in addition to improving situation, we've improved economic governance including better management of public affairs and greater domestic resource mobilization.","topic":"Mali economy","kind":"fact"},{"t":1040,"quote":"the places where millions of young people arrive at the labor market in Mali, in Burkina Faso, in Niger, and in Africa","topic":"Mali economy","kind":"fact"},{"t":1075,"quote":"Public spending is increasingly directed today towards structuring productive investment, better access to basic services and training and employment for young people and women in particular","topic":"Mali economy","kind":"fact"},{"t":1105,"quote":"Mali intends to continue its national refoundation to guarantee security, well-being, and prosperity for all of its citizens.","topic":"Mali constitution","kind":"fact"},{"t":1122,"quote":"we we count first and foremost on ourselves in this.","topic":"Mali constitution","kind":"fact"},{"t":1194,"quote":"And here we're talking about cooperation, not and not the law of the strongest to govern the world.","topic":"Mali foreign policy","kind":"fact"},{"t":1222,"quote":"Our objective here is strategic autonomy for Mali, strategic autonomy for the Confederation of the Sahel states states, the strategic autonomy for Africa in both security and development areas.","topic":"Mali foreign policy","kind":"fact"},{"t":1249,"quote":"Climate change and desertification for Mali and the Sahel remain a major source of economic, social, environmental vulnerability.","topic":"Mali climate","kind":"fact"},{"t":1259,"quote":"They affect agriculture and livelihoods. They also, we have to acknowledge it, uh threatening peace and security.","topic":"Mali climate","kind":"fact"},{"t":1300,"quote":"the world is experiencing extraordinary technological advances, including generative artificial intelligence. It is something that comes up in debate after debate.","topic":"AI policy","kind":"fact"},{"t":1312,"quote":"AI offers enormous opportunities, and we acknowledge it, but also significant risks.","topic":"AI policy","kind":"fact"},{"t":1367,"quote":"the head of state of the Republic of Mali, Assimi Goïta, um has established Mali's Center for Artificial Intelligence Robotics to promote our country's digital sovereignty.","topic":"Mali AI","kind":"fact"},{"t":1390,"quote":"Mali, therefore, reaffirms its attachment to international cooperation and considers human mobility as a benefit for humanity.","topic":"Mali AI","kind":"fact"},{"t":1441,"quote":"Mali recalls that the multilateral framework, which is embodied by the United Nations, stands at a crossroads.","topic":"UN reform","kind":"fact"},{"t":1461,"quote":"A United Nations that is more just, more representative, and truly at the service of all of the people in the world without distinction.","topic":"UN reform","kind":"fact"}],"promises":[{"t":109,"quote":"I also would like to take this opportunity to pay tribute to your predecessor for the remarkable conduct of the work of the 80th session. And finally, I wish to express our sincere appreciation to Mr.","topic":"UNGA","kind":"promise"},{"t":783,"quote":"will continue to conduct its diplomacy on the basis of good neighborly relations, mutual respect, non-interference in the domestic affairs of other states, and the peaceful settlement of disputes.","topic":"Mali counter-terrorism","kind":"promise"},{"t":937,"quote":"the government remains committed to implementing the Malicura 2063 vision and the national strategy for emergence and sustainable development 2024-2033.","topic":"Mali sovereignty","kind":"promise"},{"t":1499,"quote":"Mali reaffirms its readiness to contribute to common efforts of the international community for a world which is more peaceful, more secure, more just, more prosperous, and finally more united.","topic":"UN reform","kind":"promise"}],"attacks":[{"t":265,"quote":"The blatant violations of international its selective application, double standards in the management of crises throughout the world, abusive recourse to force and threats, and policies of hegemony and domination","topic":"UN sanctions","target":"Hegemonic Powers"},{"t":326,"quote":"the slowness of anticipation within the United Nations, which too often leaves the organization reduced to observing crisis after they have erupted","topic":"UN sanctions","target":"United Nations"},{"t":397,"quote":"strong condemnation of international terrorism and its foreign state sponsors, who finance, arm, provide legit- logistical support, and intelligence to this organized transnational crime.","topic":"Libya","target":"Foreign State Sponsors of Terrorism"},{"t":444,"quote":"Here we have a country which claims to be protecting its territorial integrity, whereas in Africa, in the Sahel, it provides clear support to terrorist and other harmful group groups which undermine the territorial integrity of our countries","topic":"Ukraine","target":"Ukraine"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":null,"text":"I now give the floor to his Excellency Minister of Foreign Affairs and International Cooperation of Mali. Mr. President Mr. President of the General Assembly, your Excellencies, heads of state and government, Mr."},{"t":65,"topic":"UNGA","text":"Secretary-General, ladies and it is a great honor for me to address this august assembly on behalf of his Excellency General Assimi Goïta, President of the transition and head of state, and to deliver the statement of the Republic of Mr. President, please allow me to warmly congratulate you on your election as uh president of the 81st session of the General Assembly, and from the outset, I assure you of Mali's full cooperation throughout your I also would like to take this opportunity to pay tribute to your predecessor for the remarkable conduct of the work of the 80th session. And finally, I wish to express our sincere appreciation to Mr."},{"t":126,"topic":"Mali independence","text":"Antonio Guterres, Secretary-General of the United Nations, for his commitment over the past 10 years in the service of our organization and in the service of peace, development, and human rights throughout the world. Your Excellencies, ladies and gentlemen, um exactly 66 years ago, six days only after becoming independent and sovereign, Mali, under the leadership of President Modibo Keïta, to the UN with the support of the Republic of uh Tunisia and uh of the salon, currently Sri Lanka. We welcome the theme of the 81st session of the General Assembly, namely restoring trust, supporting transformation, a United Nations organization that delivers for all."},{"t":195,"topic":"Mali UN","text":"This theme is uh very timely and because beyond encouraging reflection on how our organization can regain and effectiveness um mid multiple crises and challenges to multilateralism, especially calls on member states to restore trust and seek common solutions to the many many challenges of our time. And how can this be achieved? For its part, Mali reaffirms its unwavering commitment to reformed founded on strict respect respect for the purposes and principles of the United Nations Charter, particularly sovereign equality, territorial integrity, non-use of force, mutual respect, and non-interference in the internal affairs of a state. The further we move away from these principles, the closer we come to cycles of conflict, and we all know that."},{"t":265,"topic":"UN sanctions","text":"The blatant violations of international its selective application, double standards in the management of crises throughout the world, abusive recourse to force and threats, and policies of hegemony and domination in violation of the charter of this organization have seriously undermined public confidence throughout the world in international institutions, especially the United We therefore call for the lifting of unilateral coercive measures which undermine state sovereignty and endanger the well-being of populations in approximately 30 countries throughout the world which are affected by such sanctions. To these practices which undermine the current governance, we need to add the slowness of anticipation within the United Nations, which too often leaves the organization reduced to observing crisis after they have erupted."},{"t":336,"topic":"Libya","text":"That's the case in Israel, where a for several decades we had a security crisis pro- Also, the uh crisis in Libya provoked by the NATO interference in 2011. the uh NATO action in Libya significantly worsened the security, political, humanitarian, and human rights situation in our region through, in particular, the spread of terrorism and violent extremism. Now, faced with this reality, it is a legitimate to question the effectiveness of the tools available to our organization. It is for this reason that we welcome the strategic review of the United Nations Regional Office for West Africa and the Sahel, which should lead to an approach better aligned with the realities and concerns of the uh people impacted. The government of Mali reiterates its strong condemnation of international terrorism and its foreign state sponsors, who finance, arm, provide legit- logistical support, and intelligence to this organized transnational crime."},{"t":416,"topic":"Ukraine","text":"Following uh Ukraine's initial statement in 2024, in which it acknowledged support for terrorist groups operating in the Sahel, that country publicly reiterated the highest level of state is interference in Africa. And beyond our states, other independent sources also corroborate these unacceptable actions by Ukraine. Here we have a country which claims to be protecting its territorial integrity, whereas in Africa, in the Sahel, it provides clear support to terrorist and other harmful group groups which undermine the territorial integrity of our countries. Given our history, the international community, in particular Africa, cannot just remain silent in the face of what was being done by Ukraine has enormous consequences for African countries and it goes beyond than that."},{"t":482,"topic":"Mali security","text":"We understand very well that Ukraine is just a visible part of the iceberg which is trying to destabilize our country, to break our nation, to throw off the colonial yoke. which is nurtured and supported from outside does it in three ways. First in the armed way, we know that. It's attacking civilian populations, it's a security crisis. In the economic way which impacts our countries and through the media. Notably through us organized and systematic campaigns and certain media outlets nostalgic for colonial past play a role in these. The coordinated attacks of 25th April and 4th July 2026 and several locations in Mali caused numerous casualties and they demonstrate the existence of the dangerous connection that we've become increasingly aware of."},{"t":553,"topic":"Sahel security","text":"So, the scenario we witnessed in 12 in 2012 is repeating itself now with terrorist groups and so-called separatist armed groups now forming openly terrorist coalition against Malian institutions and populations. Regional and international responses, including the deployment of international forces, have failed to halt these uh complex security crises and massacres affecting the Sahelian populations. And that is why His Excellency Ibrahim Traoré of Burkina Faso president of the Confederation of Sahel um General Assimi Goïta, president of transition and head of state of Mali. Abdourahamane Tiani, president of the Republic of Niger and head of state. Our three heads of state took the historic decision on 6th July 2024 in Niamey to create the Confederation of Sahel States so as to take responsibility for the fate of our And since its establishment to date the AES Confederation has achieved real and encouraging progress in various areas."},{"t":637,"topic":"Sahel security","text":"I reaffirm here the determination of our three heads of state to pursue and intensify the fight against in all of its forms and manifestations. The Malian delegation fully endorses that statement that will be delivered by His Excellency Mr. Traoré, Minister of Foreign Affairs of Burkina Faso on behalf of the Confederation of Sahel States which brings together Burkina Faso, the Republic of Mali, and the Republic of Malian forces on their own and also within the AES unified force and with the support of the Russian Federation are today on the front line against imposed terrorism. I would even go so far as to say it's a hybrid war by proxy whose implications extend beyond our region. I also salute all partners who continue to support Mali and the countries of the Sahel in this difficult Victory against terrorism, this global existential threat, requires pulling efforts and resources, but above all, it requires a shared understanding of the phenomenon of terrorism itself."},{"t":716,"topic":"Mali counter-terrorism","text":"Because contrary what some would have us believe, there is no such a such thing as a good terrorist and a bad terrorist. The three AS member countries remain open to cooperation with all partners who respect our main principles governing our countries, namely respect for our sovereignty, territorial integrity, the respect for our strategic choices, including our choices for partnership, and also taking into account the interests of our populations. And we do not accept dictates here. rather we seek sincere healthy cooperation and partnership conducted in mutual respect. And in this spirit, in line with the principles and goals of its print of its policy, will continue to conduct its diplomacy on the basis of good neighborly relations, mutual respect, non-interference in the domestic affairs of other states, and the peaceful settlement of disputes."},{"t":798,"topic":"Mali security","text":"I would like to use this opportunity to pay tribute to all victims of the cowardly barbarism of terrorism who have sacrificed their I also would like to pay tribute to our defense and security forces for their courage, their professionalism, and their unwavering dedication in defending sovereignty, territorial integrity of our countries, and the protecting our people. I pay special tribute to the memory of General [clears throat] Sadio Camara, Minister of Defense and Veterans Affairs, whose legacy of patriotism, courage, and sacrifice will continue to inspire future generations of Malians and people in the Sahel. Mr. President, to reinforce security, and ensure the sustainable return of peace, the government is implementing a comprehensive and integrated strategy for stability and prosperity of our Uh and for this, the state continues to extend a hand to all those willing to lay down their arms and return to the Republic in line with the conclusions of inter-Malian dialogue and the national charter"},{"t":889,"topic":"Mali sovereignty","text":"for peace and reconciliation. Already, thousands of former combatants who meet the conditions have uh um either joined the defense and security forces or entered civilian employment. Mali's sovereignty is very precious to us, and it is not negotiable. Sovereignty is not limited to defending our territory. It also means we are controlling our economic choices, that we are managing and developing our natural resources and mining resources, our gold and lithium. Strengthening our productive sectors and also creating greater opportunities for our youth. And in this spirit, the government remains committed to implementing the Malicura 2063 vision and the national strategy for emergence and sustainable development 2024-2033."},{"t":951,"topic":"Mali economy","text":"These two ambitious programs are designed to meet the legitimate aspirations of the Malian and they constitute a generational pact. And it shows our determination to build a sovereign state, a competitive economy, a just society, a country in which every citizen can thrive with The government placed at the heart of its action economic recovery and public because they're essential to lasting peace and stability. Thus, through appropriate reforms, the government, in addition to improving situation, we've improved economic governance including better management of public affairs and greater domestic resource mobilization. Man, my country today, I must say, works very hard to mobilize the resources that we need the international assistance on its own, however great it is, never developed a country."},{"t":1029,"topic":"Mali economy","text":"If we looked today, the level of international assistance and we compare that with the needs for financing in our countries, the places where millions of young people arrive at the labor market in Mali, in Burkina Faso, in Niger, and in Africa. We can see that the international assistance will never be enough, and we need to mobilize our own resources, and we need to have confidence that we will be able to have other sources of our funding. So, that our country can move forward. So, our country was will continue counting on their own while still leaving the door open who want to work with us. Public spending is increasingly directed today towards structuring productive investment, better access to basic services and training and employment for young people and women in particular. And this requires greater local processing of our natural and mining resources, stronger national production capacities, and an active role for youth in Mali's economic and social transformation."},{"t":1105,"topic":"Mali constitution","text":"Mali intends to continue its national refoundation to guarantee security, well-being, and prosperity for all of its citizens. And once again, we we count first and foremost on ourselves in this. Mr. President, now, regional international issues. The government remains attentive to developments across Africa and around the world, and we encourage, therefore, efforts aimed at the rapid and lasting resolution of conflicts on the African continent. Um regarding the situation in the Middle East, Mali reaffirms its full support for the for the brotherly Palestinian people and their legitimate struggle to exist as a fully recognized state. Mr. President, international situation is such that we have to acknowledge the international order is undergoing profound change."},{"t":1173,"topic":"Mali foreign policy","text":"And the longer we ignore it, the less we will we will be able to adjust to it. The question is no longer whether the world is moving towards multipolarity, but rather which actors will shape this new order and how will they cooperate to meet the aspirations of people throughout the planet we share. And here we're talking about cooperation, not and not the law of the strongest to govern the world. In this changing environment, Mali will pursue a foreign policy based on sovereign equality of states, on diversified partnerships, on defense of national interests, constructive engagement for peace and prosperity throughout the world. Our objective here is strategic autonomy for Mali, strategic autonomy for the Confederation of the Sahel states states, the strategic autonomy for Africa in both security and development areas."},{"t":1237,"topic":"Mali climate","text":"And this autonomy does not mean a rupture, rather it seeks to make Africa into a credible and indispensable partner for global stability and prosperity. Climate change and desertification for Mali and the Sahel remain a major source of economic, social, environmental vulnerability. They affect agriculture and livelihoods. They also, we have to acknowledge it, uh threatening peace and security. We therefore call on member states to focus on adaptation, on access to climate finance, on indigenous technologies and solutions tailored to Sahelian realities. We advocate stronger links between efforts to combat desertification, food security initiatives, water management, conflict prevention, and resilience building. Mr."},{"t":1298,"topic":"AI policy","text":"President, the world is experiencing extraordinary technological advances, including generative artificial intelligence. It is something that comes up in debate after debate. AI offers enormous opportunities, and we acknowledge it, but also significant risks. We um must be lucid here. We must not simply consume AI technology, we must master it, adapt it to our realities, and contribute to its development. and creating appropriate legal and ethical frameworks. For us, digital and technological sovereignty has become an essential dimension of national sovereignty. We must invest in skills, in research, in in in innovation, and infrastructure, so that young people can participate fully in this transformation."},{"t":1366,"topic":"Mali AI","text":"For this reason, the head of state of the Republic of Mali, Assimi Goïta, um has established Mali's Center for Artificial Intelligence Robotics to promote our country's digital sovereignty. On the issue of international migration, which is a country of origin, transit, and destination at the same time. Mali, therefore, reaffirms its attachment to international cooperation and considers human mobility as a benefit for humanity. It is important in this room to say it to repeat it that for us, human mobility is not a It is a benefit, and all of the countries in this assembly have from migration, even though other aspects need to be managed. So, migration, mobility is a benefit for We call, therefore, for respect of the rights of the migrants in in accordance with international conventions."},{"t":1438,"topic":"UN reform","text":"Mr. President, by way of conclusion, Mali recalls that the multilateral framework, which is embodied by the United Nations, stands at a crossroads. The time has come for us to assume our shared responsibility for a reformed United Nations, I was going to say. That's how vast the scope of work is. A United Nations that is more just, more representative, and truly at the service of all of the people in the world without distinction. This is an essential condition to restoring the trust of member states and people in the organization. It requires strengthening representation within multilateral institutions, including multilateral financial institutions, and ensuring that Africa's voice is heard more clearly in decision-making bodies which affect the future of world, the future of humankind. Mali reaffirms its readiness to contribute to common efforts of the international community for a world which is more peaceful, more secure, more just, more prosperous, and finally more united."},{"t":1514,"topic":null,"text":"I thank you. &gt;&gt; I thank the Minister for Foreign Affairs and International Cooperation of Mali."}],"compare":[{"topic":"Mali","share":0.1545,"mean":0.0002,"rank":1,"others":1},{"topic":"UN & its reform","share":0.1458,"mean":0.2051,"rank":120,"others":170},{"topic":"Africa","share":0.1136,"mean":0.023,"rank":15,"others":36},{"topic":"Libya","share":0.0515,"mean":0.0025,"rank":6,"others":5},{"topic":"Artificial Intelligence","share":0.0472,"mean":0.0505,"rank":81,"others":83},{"topic":"Russia-Ukraine War","share":0.0452,"mean":0.0353,"rank":45,"others":44}]};
